UPDATE companies SET description='LMC Industries was founded in 1945 in Arnold, Missouri, by toolmaker Fred Suellentrop, Sr., who set out to build high-quality equipment that would improve the manufacturability of essential products. The company remains family-owned today, operating from a 240,000-square-foot facility in the St. Louis metro area.

The company operates as a contract manufacturer specializing in precision metal stamping — including progressive die stamping, in-die tapping, and in-die assembly — and plastic injection molding, insert molding, and overmolding. It also maintains a 14,000-square-foot tool room equipped with CNC milling, wire and conventional EDM, water jet machining, and TIG welding for in-house die and mold fabrication, repair, and maintenance. Additional in-house capabilities include welding, riveting, chemical passivation, and assembly, supported by partner networks for heat treating and metal finishing.

LMC serves OEMs and tiered suppliers across automotive, agricultural, consumer products, medical device, and hand-tool markets. Its components appear in every major automotive program worldwide, in harvesting equipment and livestock feeding systems, in medical device grips, and in everyday items such as screwdriver handles, toothbrush handles, and the press-down valve on whipped topping cans.

The company differentiates itself by housing both metal and plastic production under one roof, enabling single-source accountability, compressed lead times, and integrated design-for-manufacturability (DFM) reviews across materials. Its quality system follows APQP and PPAP protocols with first-article inspections, and its transfer-tooling process allows it to take over existing programs with minimal disruption.', certifications=ARRAY['ISO9001','IATF16949']::text[], profile='{"capabilities": ["Precision metal stamping", "Progressive die stamping", "In-die tapping", "In-die assembly", "Plastic injection molding", "Insert molding", "Overmolding", "Tool and die fabrication", "Tool and die maintenance", "Assembly and finishing", "Welding", "Riveting", "Chemical passivation", "Heat treating (via partners)", "Metal finishing (via partners)", "Logistics and kitting", "EDI technology", "Supply replenishment programs", "Advanced shipping notice (ASN)", "Design for Manufacturability (DFM) support", "Production Part Approval Process (PPAP) support", "Advanced Product Quality Planning (APQP) review", "Tooling audit", "Transfer tooling management"], "industries": ["Automotive", "Agricultural", "Consumer products", "Medical device", "Hand tools"], "materials": [], "equipment": ["CNC milling", "Wire EDM", "Conventional EDM", "Water jet machining", "TIG welding", "Stamping presses (20)", "Plastic injection molding presses (80+ total presses)"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Single-source metal stamping and plastic molding under one roof", "In-house tool room with CNC, EDM, water jet, and TIG welding for die and mold maintenance", "Design for Manufacturability (DFM) applied to every program across metal and plastic", "APQP/PPAP quality processes with first-article inspections", "Family-owned since 1945 with over 75 years of metal forming expertise"], "facts_used": ["Founded 1945 by Fred Suellentrop Sr. -> /about-us", "Family-owned -> /about-us", "Headquarters Arnold, Missouri -> db", "240,000+ sq ft manufacturing space -> /", "14,000 sq ft tool room -> /capabilities", "20 stamping presses, 80+ total presses -> /", "Capabilities: precision metal stamping, progressive die stamping, in-die tapping, in-die assembly, plastic injection molding, insert molding, overmolding -> /capabilities", "Tool room equipment: CNC milling, wire EDM, conventional EDM, water jet machining, TIG welding -> /capabilities", "Certifications: ISO9001, IATF16949 -> db", "Industries: automotive, agricultural, consumer products, medical device, hand tools -> /, /about-us, /capabilities", "Quality processes: APQP, PPAP, first article inspections -> /quality, /", "Transfer tooling process -> /capabilities", "DFM applied to every program -> /capabilities", "Single-source metal and plastic under one roof -> /capabilities", "Press-down valve on whipped topping cans example -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We design and fabricate metal stamping parts and plastic injection molded parts either as standalone products or combined as insert-molded or over-molded assemblies.", "founded_year": "1945", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='lmc-industries-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Locust Grove Woodworks operates from Thorndike, Maine, where the founder has been building fine furniture and wood products since 1982. The owner’s background in Amish and Mennonite communities shaped a philosophy of simplicity, durability, and sustainable craftsmanship that still guides the shop today.

The shop produces handcrafted solid‑wood furniture one piece at a time, using a mix of hand tools, power tools, and draft‑horse‑driven lineshafts. Construction relies on traditional joinery such as sliding dovetails and floating tenons to accommodate wood movement, and finishes are limited to linseed oil and wax. The product range includes beds, chairs, clocks, coffins, cradles, desks, tables, casework, and custom pieces in Shaker, Colonial, and Mission styles.

Customers are primarily residential buyers seeking heirloom‑quality furniture that can be passed down through generations. The maker also serves clients looking for custom casework and specialty items such as coffins and cradles, all built to order without plywood or particle board.

The business was started to create beautiful, enduring furniture in the most sustainable manner possible — originally using only literal horsepower and hand tools. The founder cites the Shaker principle of building as though to live a thousand years but die tomorrow as a guiding ethos, and continues to transition toward horse‑powered generators for electricity.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted solid wood furniture", "Custom furniture", "Casework", "Hand tool joinery", "Power tool machining", "Draft horse-powered lineshafts", "Sliding dovetail joinery", "Floating tenon joinery", "Linseed oil and wax finishing"], "industries": ["Residential furniture", "Custom woodworking", "Heirloom furniture", "Shaker-style furniture", "Colonial-style furniture", "Mission-style furniture"], "materials": ["Solid wood", "Linseed oil", "Wax"], "equipment": ["Hand tools", "Power tools", "Draft horses", "Lineshafts", "Horse treadmill (planned)"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted solid\u2011wood construction with traditional joinery", "Partially powered by draft horses and lineshafts", "Shaker, Colonial, and Mission design influences", "No plywood or particle board used", "Linseed oil and wax finishes only"], "facts_used": ["Founded 1982 -> db", "Location Thorndike, Maine -> db", "Owner background Amish/Mennonite -> /", "Shaker influence -> /", "Handcrafted solid wood furniture -> /", "Custom furniture and casework -> /", "One piece at a time, mostly alone -> /", "Draft horses and lineshafts for power -> /", "Horse treadmill planned -> /", "Sliding dovetails, floating tenons -> /", "Linseed oil and wax finishes -> /", "No plywood or particle board -> /", "Product categories: beds, chairs, clocks, coffins, cradles, desks, tables, casework -> /", "Shaker, Colonial, Mission styles -> /", "Sustainable philosophy -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "I have been building fine quality furniture and wood products since 1982. I still produce each piece of furniture one piece at a time.", "founded_year": "1982", "employee_count": "1", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='locust-grove-woodworks' AND approved AND profile IS NULL;
UPDATE companies SET description='The Lodge Factory Store opened in 1994 in South Pittsburg, Tennessee, as an outlet for factory seconds—cast iron pieces that fell short of the company''s exacting standards. Situated next to Lodge''s own foundries on the edge of the Cumberland Plateau, the store began as a way to offer discounted cookware directly to visitors and has since grown into a flagship retail location carrying the brand''s full product line.

The store stocks the complete range of Lodge cast iron, including classic skillets, Dutch ovens, griddles, and specialty items such as the Fluted Cake Pan and Wedge Pan. Shoppers also find enameled cast iron Dutch ovens, professional-grade carbon steel cookware, stoneware baking dishes, and a wide selection of accessories. The Blacklock collection of lightweight cast iron is featured prominently. Staff provide hands-on guidance on seasoning, cleaning, and recipe ideas, and the store offers custom skillet personalization. Online orders over $75 ship free.

The original purpose—to sell factory seconds—remains a draw, but the store now distinguishes itself through direct access to the full Lodge lineup, expert staff, and a setting that connects buyers to the source of the cookware.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Retail sales of cast iron cookware", "Factory seconds sales", "Product selection and consultation", "Seasoning and care guidance", "Custom skillet personalization", "Online order fulfillment", "Free shipping on qualifying orders"], "industries": ["Cookware retail", "Kitchenware", "Outdoor recreation", "Giftware"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Factory seconds sold at discounted prices", "Full line of Lodge cast iron, enameled, carbon steel, and stoneware", "Expert staff assistance with seasoning, care, and recipes", "Located adjacent to Lodge''s manufacturing foundries", "Free standard shipping on orders over $75"], "facts_used": ["Founded in 1994 to sell factory seconds -> /", "Located at 220 East 3rd St, South Pittsburg, TN 37380 -> /", "Hours: 7 days a week, 8:00 AM - 6:00 PM CT -> /", "Sells classic cast iron skillets, Dutch ovens, specialty items (Fluted Cake Pan, Wedge Pan), enameled cast iron, carbon steel, stoneware, accessories -> /", "Staff provides guidance on seasoning, cleaning, recipes -> /", "Offers custom skillet personalization -> /", "Free shipping on orders over $75 -> /", "Blacklock lightweight cast iron collection featured -> /", "Located next to cast iron foundries, 30 minutes from Chattanooga -> /", "Founded year 1994 from database -> db", "Headquarters South Pittsburg, Tennessee from database -> db"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Founded in 1994 to exclusively sell factory seconds (cookware that doesn''t quite meet our rigorous standards), our Factory Store has since expanded to include the full line of Lodge products.", "founded_year": "1994", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='lodge-factory-store' AND approved AND profile IS NULL;
UPDATE companies SET description='Loeb Electric was founded in 1912 in Columbus, Ohio by Oscar Avery and Arthur Loeb Sr. as the Avery & Loeb Electric Company, initially selling radio and electrical products. After a brief pause during the Great Depression, Arthur Loeb restarted the business under the Loeb Electric name. The company remains family-owned, now led by President Charles Loeb, the third generation of the Loeb family.

Today Loeb Electric operates as one of the largest independent electrical distributors in the United States. From its Columbus headquarters, the company runs four retail stores in central Ohio, four distribution centers totaling over 400,000 square feet of warehouse space, and a fleet of more than 35 delivery trucks. With 350-plus team members, the operation picks over 500 orders comprising 8,000 line items daily. Beyond stocking electrical supplies—lighting, wire, conduit, tools, and EV charging equipment—Loeb provides value-added services including vendor-managed inventory (VMI), project material management, wire cutting and harnessing, supply kitting, and 24/7 locker pickup.

The distributor serves two primary customer groups: local electrical contractors in central Ohio and national brands with multi-site footprints. Its National Accounts division supports retailers and facility operators across the country with preventative and reactive maintenance, energy-saving lighting retrofits, solar and microgrid solutions, and EV charging infrastructure. The company also works with industrial and commercial facilities on energy audits and sustainability programs.

The company emphasizes trust and personal service as its foundation, a philosophy articulated by President Charles Loeb: “This business is about trust. And we’ve earned the trust of our clients, because we provide them with personal service and demonstrate a commitment to their success.” Loeb Electric traces its longevity to continuous investment in experienced associates, technology, and training, aiming to be the partner customers can rely on for on-time delivery and jobsite productivity.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Electrical distribution", "Vendor-managed inventory (VMI)", "Project material management", "Wire cutting and harnessing", "Wire paralleling and coiling", "Pulling head installation", "Supply kitting", "Advanced shipping notifications", "Smart locker pickup (24/7)", "Timely jobsite delivery", "Convenient pickup locations", "After-hours emergency service", "Energy-saving lighting solutions", "Solar energy storage solutions", "Microgrid energy systems", "EV charging products", "Energy & facility audits", "Preventative and reactive maintenance services"], "industries": ["Electrical contractors", "National retail brands", "Commercial facilities", "Industrial facilities", "Energy and sustainability", "Solar energy", "Microgrid and distributed energy", "EV charging infrastructure"], "materials": ["Electrical wire and cable", "Conduit", "Lighting fixtures", "LED bulbs", "EV charging equipment", "Electrical tools"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned since 1912 with third-generation leadership", "400,000+ sq ft warehouse across four distribution centers", "Same-day delivery and 24/7 smart-locker pickup in central Ohio", "Vendor-managed inventory (VMI) with consigned stock options", "Wire cutting, harnessing, and pulling-head installation services", "Supply kitting customized to project specifications", "National Accounts division for multi-site retail and facility brands"], "facts_used": ["Founded 1912 in Columbus, Ohio by Oscar Avery and Arthur Loeb Sr. -> /about-us", "Family-owned and operated, third-generation leadership -> /about-us", "Headquarters in Columbus, Ohio -> /about-us", "350+ team members -> /about-us", "4 retail stores in central Ohio -> /about-us", "4 distribution centers, 400,000+ sq ft warehouse -> /about-us", "35+ delivery trucks -> /about-us", "Picks over 500 orders (8,000 lines) daily -> /about-us", "Ranked Top 50 by Electrical Wholesaling magazine -> /about-us", "Offers VMI services, project material management, wire services, supply kitting, delivery solutions -> /services", "After-hours emergency service available -> /", "Serves electrical contractors and national multi-site brands -> /about-us, /services", "Provides energy-saving lighting, solar, microgrid, EV charging solutions -> /services, /", "Leadership team includes Charles Loeb (President) -> /about-us"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We are an innovative electrical distributor committed to bringing our values to every project, every day.", "founded_year": "1912", "employee_count": "350+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='loeb-electric' AND approved AND profile IS NULL;
UPDATE companies SET description='Lotel was founded in 1964 in Baton Rouge, Louisiana, by John L. Lowery. Shortly after establishing the company, Lowery invented and patented the Mesh-Up line of concrete reinforcement chairs, which became the foundation of the business. The Mesh-Up chair was the first practical flexible chair for welded wire mesh in concrete slabs and gained immediate market recognition.

Today the company operates from its Baton Rouge facility, where it produces Mesh-Up and Rebar-Up chairs for welded wire mesh and rebar support in concrete slabs. The plant runs five injection molding machines and also provides custom molding services for outside clients. Assembly, packaging, and palletized loading are handled in-house.

Lotel’s primary customers are contractors placing concrete slabs, who rely on the chairs for proper reinforcement positioning. The patented chairs have been sold globally, with patent protection in more than 50 countries, including U.S. Patents 6,962,029; 7,458,192; and D491,443.

The company says its chairs were designed for increased stability and ease of use, and that its founding goal was to supply contractors with high-quality products at competitive prices.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom injection molding", "Mesh-Up chair manufacturing", "Rebar-Up chair manufacturing", "Load capability demonstration", "Assembly and packaging", "Palletized loading"], "industries": ["Construction", "Concrete reinforcement", "Contractors"], "materials": [], "equipment": ["Five injection molding machines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Worldwide patent protection in over 50 countries", "Five injection molding machines on site", "Custom injection molding services", "Patented chair design for increased stability and ease of use", "Focus on competitive pricing for contractors"], "facts_used": ["Founded 1964 in Baton Rouge by John L. Lowery -> /about-us", "Manufactures Mesh-Ups and Rebar-Ups -> /about-us", "Offers custom molding services -> /about-us", "Five injection molding machines -> db", "Load capability demonstration -> db", "Assembly and packaging -> db", "Palletized loading -> db", "Globally patented in over 50 countries -> /services", "U.S. Patents 6,962,029; 7,458,192; D491,443 -> /services", "Serves contractors -> /services", "Chairs designed for increased stability and ease of use -> /services", "Goal to provide contractors finest products at competitive prices -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Today we manufacture Mesh-Ups and Rebar-Ups from our facilities in Baton Rouge.", "founded_year": "1964", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='lotel' AND approved AND profile IS NULL;
