UPDATE companies SET description='Louisa Food Products, Inc. operates from St. Louis, Missouri, where it was founded over 50 years ago by Ferdinando Baldetti, a local restaurateur who began producing scratch-made ravioli and pasta for area restaurants. The business remains family-owned, now spanning four generations of the Baldetti family, and continues to be guided by the founding principle that freshness matters.

The company manufactures frozen filled pasta, including ravioli, tortellini, and toasted ravioli, using a scratch-kitchen approach. Each day, vegetables are hand-chopped and roasted, meats are braised and stocks reduced, cheeses are freshly grated, and pasta dough is mixed from semolina flour and eggs. All ingredients are USDA-graded, and production takes place in a facility that includes a culinary center for product development.

Louisa Foods serves both foodservice operators and retail consumers. The company markets directly to chefs and home cooks through recipes and pairing suggestions.

The brand differentiates itself by adhering to authentic, labor-intensive methods: no shortcuts, daily from-scratch preparation, and a commitment to fresh ingredients.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Fresh pasta production", "Filled pasta manufacturing", "Scratch cooking (vegetable prep, meat braising, stock reduction)", "Cheese grating and shredding", "Sauce production", "Culinary research and development"], "industries": ["Foodservice", "Retail"], "materials": ["USDA-graded meats", "seafood", "produce", "herbs", "semolina flour", "eggs", "domestic cheeses", "imported cheeses"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Pasta made from scratch daily using fresh ingredients", "Vegetables hand-chopped, meats braised and stocks reduced in-house", "Four-generation family pasta-making tradition", "Only USDA-graded meats, seafood, produce and herbs used", "Culinary center continuously developing new pasta products"], "facts_used": ["Location: St. Louis, MO -> db", "Family-owned, four generations -> /about", "Founder Ferdinando Baldetti -> /about", "Products: frozen filled pasta (ravioli, tortellini, toasted ravioli) -> /, /about", "Scratch kitchen methods -> /about", "USDA-graded ingredients -> /about", "Industries: Foodservice, Retail -> /", "Mission: leading provider of high-quality frozen filled pasta -> db, /about", "Culinary center developing new products -> /, /about", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Started over 50 years ago, Louisa Foods is a family-owned business. Ferdinando Baldetti, St. Louis restaurateur produced high-quality, scratch-made ravioli and pasta for local restaurants.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/louisa-foods/"], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WH